declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('PUT'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$id=requestId();$i=jsonRequest();$sets=[];$p=[':id'=>$id];foreach(['name','slug','image','status','sort_order'] as $f){if(array_key_exists($f,$i)){$value=$i[$f];if($f==='status'){$value=strtoupper((string)$value);if(!in_array($value,['ACTIVE','INACTIVE'],true))jsonResponse(false,'Invalid category status.',null,['status'=>'Use ACTIVE or INACTIVE.'],422);}$sets[]="$f=:$f";$p[":$f"]=$value;}}if(!$sets)jsonResponse(false,'No fields to update.',null,[],422);$s=$db->prepare('UPDATE categories SET '.implode(',',$sets).' WHERE id=:id');$s->execute($p);if(!$s->rowCount())jsonResponse(false,'Category not found or unchanged.',null,[],404);jsonResponse(true,'Category updated successfully.');});
